using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text.Json;
using X=Rizan.Portfolio.Xau;using E=Rizan.Portfolio.Eur;using Rizan.Portfolio;
var directory=args[0];using var summary=JsonDocument.Parse(File.ReadAllText(Path.Combine(directory,"broker_summary.json")));var since=DateTime.Parse(summary.RootElement.GetProperty("history").GetProperty("orders").GetProperty("from_utc").GetString()!,null,DateTimeStyles.AdjustToUniversal);var initial=args.Length>1?DateTime.Parse(args[1],null,DateTimeStyles.AdjustToUniversal):DateTime.MinValue;var output=new Dictionary<string,object>();
List<X.Candle> Read(string symbol)=>File.ReadLines(Path.Combine(directory,symbol+"_M1.csv")).Skip(1).Select(l=>{var p=l.Split(',');return new X.Candle(DateTime.Parse(p[0],null,DateTimeStyles.AdjustToUniversal),double.Parse(p[1],CultureInfo.InvariantCulture),double.Parse(p[2],CultureInfo.InvariantCulture),double.Parse(p[3],CultureInfo.InvariantCulture),double.Parse(p[4],CultureInfo.InvariantCulture));}).Where(b=>b.OpenUtc>=initial).ToList();
try{
var x=Read("XAUUSD");var end=x[^1].End(1);var m=X.FrozenCore.Aggregate(x,5,end);var h=X.FrozenCore.Aggregate(x,60,end);var q=X.FrozenCore.Aggregate(x,15,end);var atr=X.FrozenCore.Atr(m);var bias=X.FrozenCore.Strict(h);var raw=X.FrozenCore.XauRaw(m,atr,X.FrozenCore.AlignStrict(h,60,m),X.FrozenCore.AlignStrict(q,15,m));int hj=-1,qj=-1;var signals=new List<object>();
for(int i=0;i<m.Count;i++){var at=m[i].End(5);while(hj+1<h.Count&&h[hj+1].End(60)<=at)hj++;while(qj+1<q.Count&&q[qj+1].End(15)<=at)qj++;if(!CompressionEntry.EligibleTime(at)||hj<199||qj<199||i<99)continue;X.Signal? s=null;var r=raw[i];int side=r.Sell?-1:r.Buy?1:0;if(side!=0)s=new(at,side,0,atr[i],side>0?r.BuyAnchor:r.SellAnchor);else s=CompressionEntry.Evaluate(m,atr,i,bias[hj],at,h[hj].Count);if(s!=null&&at>=since)signals.Add(new{AtUtc=at,Side=s.Side,Atr=s.Atr,Anchor=s.Anchor,Family=side!=0?"R3_ORIGINAL":"F005_COMPRESSION"});}
output["XAUUSD"]=new{RawSignals=signals,H1Bars=h.Count,Source="FROZEN_CSHARP_CORE_ON_BROKER_M1",InitialM1Utc=x[0].OpenUtc,LastM1Utc=x[^1].OpenUtc};
}catch(Exception e){output["XAUUSD"]=new{Error=e.GetType().Name,Detail=e.Message};}
try{var x=Read("EURUSD").Select(b=>new E.Candle(b.OpenUtc,b.Open,b.High,b.Low,b.Close)).ToList();var state=new E.EurState();var f=E.FrozenCore.EurFeatures(x,x[^1].End(1),state);var s=f.Select(E.FrozenCore.EurSignal).OfType<E.Signal>().Where(s=>s.AtUtc>=since).Select(s=>new{ s.AtUtc,s.Side,s.Distance,s.AsiaExtra}).ToList();output["EURUSD"]=new{RawSignals=s,Source="FROZEN_CSHARP_CORE_ON_BROKER_M1",InitialM1Utc=x[0].OpenUtc,LastM1Utc=x[^1].OpenUtc,VirtualStateParityVerified=false};}catch(Exception e){output["EURUSD"]=new{Error=e.GetType().Name,Detail=e.Message};}
try{using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(directory,"vps.json")));var feed=doc.RootElement.GetProperty("btc_feed");if(!feed.GetProperty("extension_contiguous").GetBoolean())throw new Exception("BTC_EXTENSION_NOT_CONTIGUOUS");var bars=feed.GetProperty("bars").EnumerateArray().Select(a=>new BtcBar(DateTimeOffset.FromUnixTimeSeconds(a[0].GetInt64()).UtcDateTime,a[1].GetDouble(),a[2].GetDouble(),a[3].GetDouble(),a[4].GetDouble(),a[5].GetInt32())).ToList();var s=BtcCore.Signals(bars,BtcCore.Aggregate(bars,240)).Values.Where(s=>s.At>=since).ToList();output["BTCUSD"]=new{RawSignals=s,Source="EXACT_FROZEN_BITSTAMP_SEED_AND_VPS_EXTENSION",HourlyBars=bars.Count,Through=feed.GetProperty("through").GetInt64()};}catch(Exception e){output["BTCUSD"]=new{Error=e.GetType().Name,Detail=e.Message};}
try{using var c=JsonDocument.Parse(File.ReadAllText(Path.Combine(directory,"contracts.json")));var btc=c.RootElement.GetProperty("BTCUSD");var tz=TimeZoneInfo.FindSystemTimeZoneById(btc.GetProperty("scheduleTimeZone").GetString()!);var intervals=btc.GetProperty("schedule").EnumerateArray().Select(r=>(Start:int.Parse(r.GetProperty("startSecond").ToString()),End:int.Parse(r.GetProperty("endSecond").ToString()))).ToArray();
bool Open(DateTime at){var local=TimeZoneInfo.ConvertTimeFromUtc(at,tz);var seconds=(int)local.DayOfWeek*86400+(int)local.TimeOfDay.TotalSeconds;return intervals.Any(r=>seconds>=r.Start&&seconds<r.End);}
var sunday=DateTime.Parse("2026-11-01T23:58:00Z",null,DateTimeStyles.AdjustToUniversal);var monday=DateTime.Parse("2026-11-02T00:00:00Z",null,DateTimeStyles.AdjustToUniversal);var cachedClose=BtcWeekendPolicy.LastClose(sunday,Open);var refreshAt=sunday.AddMinutes(5);var priorLock=BtcWeekendPolicy.Monday(sunday).AddDays(7);var resultingLock=priorLock;if(monday<refreshAt&&BtcWeekendPolicy.MustFlatten(monday,cachedClose)&&(BtcWeekendPolicy.Weekend(monday)||cachedClose.HasValue)&&resultingLock<=monday)resultingLock=BtcWeekendPolicy.Monday(monday).AddDays(7);
output["BTC_WEEK_BOUNDARY_REGRESSION"]=new{CachedClose=cachedClose,RefreshAt=refreshAt,At=monday,PriorLock=priorLock,ResultingLock=resultingLock,FreshWeekClose=BtcWeekendPolicy.LastClose(monday,Open),Reproduced=resultingLock==monday.AddDays(7),Meaning="Frozen Manage/RefreshSchedule ordering can extend expired weekend lock by a week when cached close crosses Monday midnight; actual transition timestamp not journal-verified"};
}catch(Exception e){output["BTC_WEEK_BOUNDARY_REGRESSION"]=new{Error=e.GetType().Name,Detail=e.Message};}
